def fmt(x,level=0):
 if isinstance(x,dict):return '{\n'+''.join('\t'*(level+1)+fmt(k)+' = '+fmt(v,level+1)+';\n' for k,v in x.items())+'\t'*level+'}'
 if isinstance(x,list):return '('+','.join(fmt(v,level+1) for v in x)+')'
 if isinstance(x,int):return str(x)
 return json.dumps(x,ensure_ascii=False)
